/**
 * Schema fragments for the collaborative-text field type.
 *
 * A derived body declared with `e.collaborativeText()` is backed by a
 * document entity carrying two declared fields: `content`, a map whose keys
 * are cell ids (`RunCell` or `CutCell`), and `version`, a leaf written by
 * every write so a reader can refuse a cell shape it does not know.
 *
 * The document entity is generated by `defineSchema` when it expands a
 * derived field, so apps never name it unless they want per-field permission
 * granularity.
 */

import { Type } from "@sinclair/typebox";

import { buildEntityDef, e, type ConflictScope, type EntityDef } from "../entity";
import { DERIVED_DOC_ENTITY_PREFIX } from "../reserved";

/**
 * Generated document entity name for one derived field. Deterministic
 * and reserved, because the name is a wire `subject_type`, part of the
 * schema hash, and a permission string.
 */
export const generatedDocEntityName = (parent: string, field: string): string =>
  `${DERIVED_DOC_ENTITY_PREFIX}${parent}__${field}`;

/** Field on the document entity holding the cell map. */
export const DOC_CONTENT_FIELD = "content";

/** Field on the document entity carrying the cell-format version. */
export const DOC_VERSION_FIELD = "version";

/**
 * The cell format this client writes and can read. A document whose
 * `version` is anything else fails the read loudly (#698); there is no
 * legacy projection.
 */
export const CURRENT_TEXT_VERSION = 1;

/**
 * True when a relationship or a derived-field marker names a
 * collaborative-text body. One predicate so the discriminator string
 * lives in exactly one place.
 */
export const isCollaborativeText = (value: { readonly kind?: string }): boolean =>
  value.kind === "collaborative-text";

/** Anchor of a run: a character offset in another run, or the root. */
export const AnchorSchema = Type.Object({
  runId: Type.String(),
  offset: Type.Number(),
});

/**
 * TypeBox shape of an immutable run. Mirrors `RunCell` in `tree.ts`; kept
 * next to the schema layer so the document entity validates like any other
 * field.
 */
export const RunCellSchema = Type.Object({
  kind: Type.Literal("run"),
  id: Type.String(),
  text: Type.String(),
  author: Type.String(),
  stamp: Type.String(),
  anchor: AnchorSchema,
});

/** TypeBox shape of an immutable retraction over one run's characters. */
export const CutCellSchema = Type.Object({
  kind: Type.Literal("cut"),
  id: Type.String(),
  runId: Type.String(),
  from: Type.Number(),
  to: Type.Number(),
  author: Type.String(),
  stamp: Type.String(),
});

/** A cell is either a run or a cut. */
export const TextCellSchema = Type.Union([RunCellSchema, CutCellSchema]);

/**
 * One entry in the `content` map: a cell plus the map key's merge stamp.
 * The key is the cell id, so a write can only ever add a key.
 */
export const CellFieldValueSchema = Type.Object({
  value: TextCellSchema,
  update_id: Type.String(),
  hlc: Type.String(),
});

/** Field map of a generated document entity. */
export type TextDocumentFields = {
  readonly content: ReturnType<typeof e.map<typeof TextCellSchema>>;
  readonly version: ReturnType<typeof e.number>;
};

/**
 * Build the document entity for a derived body under `name`. Uses the
 * unchecked factory because the name is dynamic (a generated per-field
 * name, or the `entity` option on `e.collaborativeText`).
 */
export function buildTextDocumentEntity<N extends string>(
  name: N,
  conflictScope: ConflictScope = "field",
): EntityDef<TextDocumentFields, N> {
  return buildEntityDef(
    name,
    {
      [DOC_CONTENT_FIELD]: e.map(TextCellSchema),
      [DOC_VERSION_FIELD]: e.number(),
    },
    // A body is the heavy half of a document: the parent row is what a
    // scan or tree read wants, so the body is only materialized when opened.
    { conflictScope, materialization: "on-demand" },
  ) as unknown as EntityDef<TextDocumentFields, N>;
}
